        application, operation_details = event.split('|', 1)
        return application.strip(), operation_details.strip()
    return None

def process_events():
    events_by_application = {}
    for line in sys.stdin:
        line = line.strip()
        parsed_event = parse_event(line)
        if parsed_event:
            application, operation_details = parsed_event
            events_by_application.setdefault(application, []).append(operation_details)
        else:
            print(f"Invalid event format: {line}")

    with open('usage_log.txt', 'w') as log_file:
        for application, operations in sorted(events_by_application.items()):
            log_file.write(f"Application: {application}\n")
            for operation in operations:
                log_file.write(f"  Operation Details: {operation}\n")
            log_file.write("\n")

